object MonadExample {
  def half(x: Int): Option[Int] =
    if (x % 2 == 0) Some(x / 2) else None

  def run(x: Int): Option[Int] =
    Some(x).flatMap(half).flatMap(half)

  def demo = (run(8), run(6))
}

import scala.util.control.TailCalls.*

object TrampolineExample {
  def evenStep(n: Int): TailRec[Boolean] =
    if (n == 0) done(true) else tailcall(oddStep(n - 1))

  def oddStep(n: Int): TailRec[Boolean] =
    if (n == 0) done(false) else tailcall(evenStep(n - 1))

  def demo: Boolean = evenStep(100001).result
}

object ExecuteAroundExample {
  def around[R](acquire: () => R,
                release: R => Unit,
                action: R => Int): Int = {
    val resource = acquire()
    try action(resource)
    finally release(resource)
  }
}

object CurryingExample {
  val add: (Int, Int) => Int = (saved, x) => saved + x
  val curried: Int => Int => Int = add.curried

  def demo: Int = {
    val add5 = curried(5)
    val add100 = curried(100)
    add5(1) * 1000000 + add100(1) * 1000 + add5(1)
  }
}
